def place_delay_array(num_states, dist, delta_input_states, delta_output_states):
	
	for i in range(num_states):
		d = i * delta_input_states
		d1 = i * delta_output_states
		g.putcells(const_arr_delay, -dist - d, -dist + d)
		g.putcells(movable_arr_snark_delay, -dist - d + d1, -dist + d + d1)
		
	
def place_interpreter(num_states, num_head, delta_top_unit, delta_top_delay, delta_bottom, operation_block_dist = 1000, dist = 0, delta_input_states = 80, delta_output_states = d_head):
	dist += delta_output_states * num_states
	g.show(str(dist))
	delta_top_delay += d_head * (num_states - 2) + d_app * (num_head - 2)
	#delta_bottom += 20 + d_head * (8 - num_states) - d_app * (8 - num_head)
	
	
	delta_top_unit += num_states * delta_input_states + num_head * d_app - 357
	delta_bottom += num_states * delta_input_states + num_head * d_app
		
	place_delay_array(num_states, dist, delta_input_states, delta_output_states)
	
	g.putcells(const_SL_delay_bottom, -dist, -dist)
	g.putcells(const_SL_creator_top_snark, -dist, -dist)
	g.putcells(const_SL_creator_top_snark, -dist, -dist)
	g.putcells(const_bottom_SL, -dist, -dist)
	g.putcells(const_operation_unit, -dist, -dist)
	g.putcells(const_push_pull, -dist, -dist)
	g.putcells(ini_glider, -dist, -dist)
	
	g.putcells(movable_SL_creator_top, -dist + delta_top_unit, -dist - delta_top_unit)
	g.putcells(movable_bottom_splitter, -dist - delta_bottom, -dist + delta_bottom)
	g.putcells(movable_SL_creator_top_snarks, -dist + delta_top_unit + delta_top_delay, -dist - delta_top_unit - delta_top_delay)
	
	
	g.putcells(operation_block, -dist -operation_block_dist, -dist - operation_block_dist)
	
	return dist
def place_reg_array(num_regs):

	g.putcells(res_snark)
	
	for i in range(num_regs):
		d = d_reg * i
		g.putcells(reg, d, d)
		g.putcells(res_dup, d, d)
		
def place_SL_rule_array(rule):

	for i in range(len(rule)):
		d = d_reg * i
		g.putcells(res_dup, d - 82 - d_Rule * rule[i], d + 60 + d_Rule * rule[i])
		
		
def place_dup_array(num_head, num_tape):
	
	d_init = d_app * num_head
	dynamic_d = 0 
	
	for j in range(num_tape):
		dy = d_head * j
		
		#g.putcells(gld1, d_init + dy, -d_init - dy)
		
		for i in range(num_head):
			d = i * d_reg
			if i == num_head - 1:
				g.putcells(dup_eater, d - d_app * i + d_init + dynamic_d + dy, d + d_app * i - d_init + dynamic_d - dy)
			else:
				g.putcells(dup, d - d_app * i + d_init + dynamic_d + dy, d + d_app * i - d_init + dynamic_d - dy)
				
		dynamic_d += num_head * d_reg
	
	dy = d_head * (num_tape - 1)
	#g.putcells(gld1, -3000 + d_init + dy, -3000 -d_init - dy)
	
	d_init += d_head * num_tape +  d_head * num_head + d_head
	dynamic_d = 0 
	head_init = d_init
	
	for i in range(num_tape):
		
		for j in range(num_head):
			dy = d_head * j
		
			if j == 0:
				g.putcells(gld1, d_init + dy, -d_init - dy)
		
			if i == num_tape - 1:
				g.putcells(dup_eater,  - d_app * i + d_init + dynamic_d + dy,  d_app * i - d_init + dynamic_d - dy)
			else:
				g.putcells(dup,  - d_app * i + d_init + dynamic_d + dy,  d_app * i - d_init + dynamic_d - dy)
			
			dynamic_d += d_reg

	d_init += d_head * num_head + d_head + d_app * num_tape * num_head
	dynamic_d = 0
	
	#g.putcells(gld1, -75 + d_init, -d_init)
	g.putcells(res_ref,  -75 + d_init - 10,-d_init - 10)
	for i in range(num_head * num_tape):
		if i == num_head * num_tape - 1:
			g.putcells(dup_eater, -75 - d_app * i + d_init + dynamic_d, d_app * i - d_init + dynamic_d)
		else:
			g.putcells(dup, -75 - d_app * i + d_init + dynamic_d, d_app * i - d_init + dynamic_d)
		
		dynamic_d += d_reg
	
	return (d_init, head_init)
	
def place_state_rule_snarks(dx, head_h, num_head):
	for i in range(num_head):
		dy = i * d_Rule
		d_snark = d_head * i 
		g.putcells(snark_head1, -dx - dy - d_snark - 80, dx + dy - d_snark + 25)
		g.putcells(snark_head2, 2 * d_snark + head_h - num_head * d_head + 56 + 35, - head_h - 40 - 35 - num_head * d_head)
		
def place_head_rule(dx, rule):
	num_regs = len(rule)
	
	for i in range(num_regs):
		d = d_reg * i
		dy = rule[i] * d_Rule
		
		g.putcells(res_dup, -dx + d - dy - 2 * d_app, dx - 2 * d_app + d + dy)

def place_rl_rule(dx, rule):
	num_regs = len(rule)
	
	for i in range(num_regs):
		d = d_reg * i
		dy = rule[i] * d_Rule
		g.putcells(reflect_push_pull, -dx + d - dy, dx + d + dy)

def init_tape(dist, tape, delta, block_dist, ini_height, num_states):
	ini_SL = g.parse("bo$obo$b2o!", -block_dist-1503+ini_height-142-40 * (num_states - 3), -block_dist-1724-ini_height+142+40 * (num_states - 3))
	
	d = delta * 9
	
	for i in range(len(tape)):
		g.putcells(ini_SL, i * 9 -dist - d + tape[i] * d_head, i * 9 -dist - d - tape[i] * d_head)

def parse_turing_rule(rule_str):
	lines = rule_str.split("\n")
	
	dx = 50 - int(lines[1])
	tape = [0 for i in range(100)]
	
	init_tape = lines[0].split(" ")
	
	for i in range(len(init_tape)):
		
		try:
			tape[dx + i] = int(init_tape[i])
		except ValueError:
			break 
			
	del lines[0]
	del lines[0]
	
	num_head = 1
	num_states = 1

	lines.sort()
	
	while len(lines[0].split(" ")) < 5:
			del lines[0]
		
	for l in lines: 
		if len(l.split(" ")) < 5:
			continue
			
		state = int(l.split(" ")[0])
		head = int(l.split(" ")[1])
		
		if state + 1 > num_states:
			num_states = state + 1
	
		if head + 1 > num_head:
			num_head = head + 1
	
	if len(lines) < num_head * num_states:
		g.exit("missing rule inputs")
	
	rule_head = [0 for i in range(num_states*num_head)]
	rule_state = [0 for i in range(num_states*num_head)]
	rule_rl  = [0  for i in range(num_states*num_head)]
		
	for i in range(len(lines)):
		l = lines[i].split(" ")
		rule_state[i] = num_states - 1 -int(l[2])
		rule_head[i] =  num_head - 1 -int(l[3])
		
		if "r" in l[4]:
			rule_rl[i] = 0
		else:
			rule_rl[i] = 1
		
	return (num_head, num_states, tape, rule_head, rule_state, rule_rl)
g.new("")
operation_block_dist = 1000 

num_head, num_states, tape, rule_head, rule_state, rule_rl = parse_turing_rule(g.getclipstr())

